package com.cognia.api.adapter.out.persistence;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="intento_actividad_practica") public class PracticeAttemptJpaEntity { @Id @GeneratedValue private UUID id; @Column(name="estudiante_id") private UUID studentId; @Column(name="actividad_id") private UUID activityId; @Column(name="opcion_seleccionada_id") private UUID selectedOptionId; @Column(name="respuesta_dada") private String answer; @Column(name="es_correcta") private boolean correct; @Column(name="segundos_empleados") private Integer seconds; protected PracticeAttemptJpaEntity(){} public PracticeAttemptJpaEntity(UUID studentId,UUID activityId,UUID option,String answer,boolean correct,Integer seconds){this.studentId=studentId;this.activityId=activityId;this.selectedOptionId=option;this.answer=answer;this.correct=correct;this.seconds=seconds;} public UUID getId(){return id;} public UUID getStudentId(){return studentId;} public UUID getActivityId(){return activityId;} public UUID getSelectedOptionId(){return selectedOptionId;} public String getAnswer(){return answer;} public boolean isCorrect(){return correct;} public Integer getSeconds(){return seconds;} }
